import {enablePageSwipe} from './swipe.js';
import {loginPage} from './login.js';
import {loadHeroes,resolveRoute,readPreferences,savePreferences,hasResults} from './model.js';
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',spots:'<path d="m12 3 8 6-8 12-8-12Z"/><path d="M4 9h16M12 3v18"/>',analysis:'<path d="M4 20V9m8 11V4m8 16v-8"/>',dna:'<path d="M7 3c0 8 10 10 10 18M17 3c0 8-10 10-10 18M8 6h8M7 18h10M9 10h6M9 14h6"/>',journey:'<path d="M6 20V6h12l-3 4 3 4H6"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',hands:'<rect x="4" y="5" width="10" height="15" rx="2"/><path d="m10 5 7-2 4 14-7 2M8 10l2 2-2 2-2-2Z"/>',interfaces:'<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 21h8M12 16v5M7 8h4M7 11h9"/>',shield:'<path d="m12 3 8 3v7c0 4-8 8-8 8s-8-4-8-8V6Z"/><path d="m8 12 3 3 5-6"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spots}</svg>`;
let storage;try{storage=localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error()}}}const editorAccess=new URLSearchParams(location.search).get('editor')==='1';let authenticated=false;try{authenticated=sessionStorage.getItem('stackup.authenticated')==='1'}catch{}let prefs=readPreferences(storage);let state={status:'loading',data:null};let activeFilter='all';const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');let lastFocus;
const nav=[['home','home','INÍCIO'],['spots','spots','SPOTS'],['analysis','analysis','ANÁLISE'],['dna','dna','POKER DNA'],['profile','profile','PERFIL']];
const heading=(label,title,desc)=>`<div class="page-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p>${desc}</p></div><span class="chapter-tag">SÉRIE 02</span></div>`;
const safe=(value)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const empty=(symbol,title,desc,href='home',cta='VOLTAR AO INÍCIO')=>`<section class="empty"><div class="empty-symbol">${icon(symbol)}</div><span class="eyebrow">SUA HISTÓRIA COMEÇA AQUI</span><h2>${title}</h2><p>${desc}</p><a class="primary" href="#${href}">${cta} <span>→</span></a></section>`;
const formatControl=()=>`<div class="format-control" aria-label="Formato de jogo"><button data-format="tournament" aria-pressed="${prefs.format==='tournament'}">TORNEIOS</button><button data-format="cash" aria-pressed="${prefs.format==='cash'}">CASH GAME</button></div>`;
function openDialog(title,body){lastFocus=document.activeElement;document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').textContent=body;dialog.showModal()}
dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('#dialog-action').onclick=()=>dialog.close();dialog.addEventListener('close',()=>lastFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const features=[['spots','spots','PROVA DE SPOTS','DECISÕES NA MESA PARA ALIMENTAR O SEU POKER DNA.','01'],['analysis','analysis','ANÁLISE DE JOGO','AVALIAÇÃO DETALHADA DAS AÇÕES COM 30 INDICADORES.','02'],['dna','dna','SEU POKER DNA','O SEU JOGO REAL, ARQUÉTIPO E EVOLUÇÃO PESSOAL.','03'],['hands','hands','ANÁLISE DE MÃOS COM IA','UM ESPAÇO PARA REVISAR E ENTENDER SUAS DECISÕES.','04'],['interfaces','interfaces','INTEGRAÇÃO COM INTERFACES','CONECTE SUAS FONTES DE JOGO E AMPLIE SUA LEITURA.','05'],['profile','profile','PERFIL E AJUSTES','CONTA, HISTÓRICO E PREFERÊNCIAS.','06']];
function home(){return heading('HEROES · O PRIMEIRO ESPELHO','DESCUBRA O SEU POKER DNA.','SUAS DECISÕES CONTAM UMA HISTÓRIA. VAMOS DESCOBRIR QUAL.')+`<section class="hero heroes-hero"><img class="hero-image" src="assets/pokerino-heroes.webp" alt="Pokerinno como anfitrião do universo Heroes"><div class="hero-copy"><span class="eyebrow">CAPÍTULO 01 · RECONHEÇA SEU JOGO</span><h2>TODO JOGADOR<br>TEM UM <em>HERÓI.</em><br>QUAL É O SEU?</h2><p>POKERINNO ACOMPANHA VOCÊ NA DESCOBERTA DA SUA IDENTIDADE NA MESA.</p><a href="#mission" class="primary">INICIE O DIAGNÓSTICO. <span>→</span></a></div><div class="hero-note">SEU PODER ESTÁ NAS SUAS DECISÕES.</div></section><div class="section-top"><h2>ESCOLHA SUA PRÓXIMA MISSÃO.</h2><span>SEU JOGO. SEU CAMINHO.</span></div><div class="grid heroes-grid">${features.map(([route,symbol,title,desc,n])=>`<a class="feature" href="#${route}"><span class="mission-number">${n}</span><span class="badge">${icon(symbol)}</span><h3>${title}</h3><p>${desc}</p><span class="feature-arrow">↗</span></a>`).join('')}</div><a class="journey-strip" href="#journey"><span class="strip-emblem">${icon(shieldName())}</span><div><span class="eyebrow">SUA JORNADA NO HEROES</span><h3>OBSERVAR → DESCOBRIR → EVOLUIR</h3><p>PRIMEIRO CONHEÇA SEU JOGO. DEPOIS, ESCOLHA COMO EVOLUIR.</p></div><span>→</span></a>`}
function shieldName(){return 'shield'}
function mission(){return heading('SUA PRIMEIRA MISSÃO','UM ESPELHO PARA SUAS DECISÕES.','O DIAGNÓSTICO COMEÇA PELO JOGO QUE VOCÊ QUER CONHECER.')+`<div class="mission-layout"><section class="mission-panel"><span class="eyebrow">ESCOLHA SEU FORMATO</span><h2>ONDE VOCÊ JOGA?</h2><p>A JORNADA RESPEITA A DINÂMICA DA SUA MESA.</p>${formatControl()}<div class="mission-step"><span>01</span><div><h3>DECIDA NA MESA</h3><p>ENFRENTE OS SPOTS DISPONÍVEIS NO MOTOR.</p></div></div><div class="mission-step"><span>02</span><div><h3>RECONHEÇA SEUS PADRÕES</h3><p>VEJA A LEITURA DAS SUAS DECISÕES.</p></div></div><div class="mission-step"><span>03</span><div><h3>DESCUBRA SEU POKER DNA</h3><p>CONHEÇA SUA IDENTIDADE A PARTIR DO JOGO REAL.</p></div></div><a href="#spots" class="primary">EXPLORAR A PROVA DE SPOTS <span>→</span></a></section><section class="host-panel"><img src="assets/pokerino-heroes.webp" alt="Pokerinno convida você para a primeira missão"><div><span class="eyebrow">POKERINNO TEM UM CONVITE</span><h2>CONHECER SEU JOGO<br>É O PRIMEIRO PODER.</h2><p>SEUS RESULTADOS APARECERÃO APÓS SUAS DECISÕES REAIS.</p></div></section></div>`}
function render(){if(!location.hash||location.hash==='#login'||(!authenticated&&!editorAccess)){if(location.hash&&location.hash!=='#login')location.hash='login';loginPage(app,'HEROES');return}document.body.classList.remove('login-screen');const route=resolveRoute(location.hash);document.documentElement.classList.toggle('reduced-motion',prefs.reducedMotion);for(const id of ['navigation','mobile-navigation'])document.getElementById(id).innerHTML=nav.map(([key,symbol,title])=>`<a class="${id==='navigation'?'nav-link ':''}${route===key?'active':''}" href="#${key}" ${route===key?'aria-current="page"':''}><span class="nav-symbol">${icon(symbol)}</span>${title}</a>`).join('');
if(state.status==='loading'){app.innerHTML=heading('HEROES','PREPARANDO SUA JORNADA.','SÓ UM INSTANTE.');return}if(state.status==='error'){app.innerHTML=empty('shield','SUA JORNADA CONTINUA.','NÃO CONSEGUIMOS CARREGAR OS DADOS. TENTE NOVAMENTE EM INSTANTES.')+'<button class="primary" data-retry>TENTAR NOVAMENTE →</button>';return}
if(route==='home')app.innerHTML=home();else if(route==='mission')app.innerHTML=mission();
else if(route==='spots')app.innerHTML=heading('MISSÃO 01 · DECIDIR','A MESA É O SEU ESPELHO.','CADA DECISÃO REAL AJUDA A REVELAR SEU JOGO.')+formatControl()+empty('spots','SEUS PRIMEIROS SPOTS ESTÃO A CAMINHO.','A PROVA SERÁ LIBERADA QUANDO O MOTOR DE SPOTS ESTIVER CONECTADO AO SERVIÇO DE PRODUÇÃO.','mission','VER MINHA MISSÃO');
else if(route==='analysis')app.innerHTML=heading('MISSÃO 02 · OBSERVAR','LEIA O SEU JOGO.','30 INDICADORES. UMA LEITURA DAS SUAS DECISÕES REAIS.')+`<div class="filter-bar" aria-label="Filtrar análise">${[['all','VISÃO GERAL'],['patterns','PADRÕES'],['history','HISTÓRICO']].map(([key,label])=>`<button data-filter="${key}" aria-pressed="${key===activeFilter}">${label}</button>`).join('')}</div>`+(hasResults(state.data)?`<div class="list">${state.data.results.map(r=>`<div class="chapter"><div><h3>${safe(r.title||'RESULTADO')}</h3><p>${safe(r.summary||'')}</p></div></div>`).join('')}</div>`:empty('analysis',activeFilter==='history'?'AINDA NÃO HÁ HISTÓRICO.':activeFilter==='patterns'?'SEUS PADRÕES AINDA NÃO FORAM IDENTIFICADOS.':'SUA ANÁLISE AINDA VAI COMEÇAR.','OS INDICADORES SERÃO EXIBIDOS APÓS A LEITURA DAS SUAS DECISÕES. SEM NOTAS, GRÁFICOS OU PERCENTUAIS INVENTADOS.','spots','EXPLORAR SPOTS'));
else if(route==='dna')app.innerHTML=heading('MISSÃO 03 · DESCOBRIR','SUA IDENTIDADE NA MESA.','O POKER DNA NASCE DO SEU JOGO, AO LONGO DO TEMPO.')+`<section class="dna-stage"><div class="dna-emblem">${icon('dna')}</div><span class="eyebrow">IDENTIDADE EM CONSTRUÇÃO</span><h2>SEU ARQUÉTIPO<br>AINDA SERÁ REVELADO.</h2><p>UM PERFIL SÓ FAZ SENTIDO QUANDO REFLETE SUAS DECISÕES. COMECE PELA SUA PRIMEIRA MISSÃO.</p><a href="#mission" class="primary">CONHECER MINHA MISSÃO →</a></section><div class="dna-facts"><div><span>IDENTIDADE</span><p>AGUARDANDO DIAGNÓSTICO</p></div><div><span>EVOLUÇÃO</span><p>SEM ATIVIDADES REGISTRADAS</p></div><div><span>CONQUISTAS</span><p>SUA HISTÓRIA VAI COMEÇAR</p></div></div>`;
else if(route==='hands')app.innerHTML=heading('OBSERVE CADA DETALHE','SUAS MÃOS CONTAM HISTÓRIAS.','UM ESPAÇO PARA ENTENDER AS DECISÕES DO SEU JOGO.')+empty('hands','SUA REVISÃO COMEÇA COM UMA MÃO.','A IMPORTAÇÃO E A ANÁLISE COM IA SERÃO HABILITADAS QUANDO O SERVIÇO DE PRODUÇÃO ESTIVER DISPONÍVEL.')+'<button class="quiet" data-integration="ANÁLISE DE MÃOS COM IA">COMO FUNCIONA? ↗</button>';
else if(route==='interfaces')app.innerHTML=heading('AMPLIE SUA LEITURA','SEU JOGO, EM UM SÓ LUGAR.','ESTRUTURA PRONTA PARA CONECTAR SUAS FONTES DE JOGO.')+empty('interfaces','NENHUMA INTERFACE CONECTADA.','AS FONTES COMPATÍVEIS APARECERÃO AQUI APÓS A INTEGRAÇÃO. NENHUM ACESSO A CONTAS OU HISTÓRICOS FOI SOLICITADO.')+'<button class="quiet" data-integration="INTEGRAÇÃO COM INTERFACES">CONHECER A INTEGRAÇÃO ↗</button>';
else if(route==='journey')app.innerHTML=heading('SÉRIE 02 · TEXAS HOLD’EM','UM PASSO DE CADA VEZ.','POKERINNO ACOMPANHA VOCÊ. CADA APP TEM SUA PRÓPRIA MISSÃO.')+`<div class="list">${[['ACADEMY','APRENDER → PRATICAR → JOGAR','A BASE PARA CHEGAR À MESA.'],['HEROES','OBSERVAR → DESCOBRIR → EVOLUIR','CONHEÇA A IDENTIDADE DO SEU JOGO.'],['GRINDER EVO','TREINO DE DECISÕES','APROFUNDE SUAS DECISÕES EM TEXAS HOLD’EM.'],['REVOLUTION','SIMULAÇÃO DE JOGO','EXPLORE SITUAÇÕES E EXPERIÊNCIAS NA MESA.']].map(([name,title,desc],i)=>`<button class="chapter ${name==='HEROES'?'current-chapter':''}" data-series="${name}"><span class="number">0${i+1}</span><div><span class="eyebrow">${name}${name==='HEROES'?' · VOCÊ ESTÁ AQUI':''}</span><h3>${title}</h3><p>${desc}</p></div><span class="status">↗</span></button>`).join('')}</div><div class="quote">CADA PRODUTO TEM SUA PRÓPRIA PROPOSTA. SUA JORNADA NÃO EXIGE CONCLUIR UM APP PARA EXPLORAR O OUTRO.<small>STACKUP HOLD’EM · SÉRIE POKERINNO</small></div>`;
else if(route==='profile')app.innerHTML=heading('SUA JORNADA, DO SEU JEITO','PERFIL E AJUSTES.','CONTA, HISTÓRICO E PREFERÊNCIAS.')+`<section class="profile-intro"><span class="profile-emblem">${icon('profile')}</span><div><span class="eyebrow">SEU PRÓXIMO CAPÍTULO</span><h2>OLÁ, JOGADOR.</h2><p>GERENCIE SUA CONTA, HISTÓRICO E PREFERÊNCIAS.</p></div><button class="primary" data-login>ACESSAR CONTA →</button></section><div class="setting"><div><h3>FORMATO DE JOGO</h3><p>DEFINE O CONTEXTO DA SUA MISSÃO.</p></div>${formatControl()}</div><div class="setting"><div><h3>REDUZIR MOVIMENTOS</h3><p>UMA EXPERIÊNCIA COM MENOS ANIMAÇÕES.</p></div><input type="checkbox" id="motion" aria-label="Reduzir movimentos" ${prefs.reducedMotion?'checked':''}></div><div class="setting"><div><h3>HISTÓRICO</h3><p>SUAS ATIVIDADES REAIS FICARÃO AQUI.</p></div><a class="quiet" href="#analysis">CONSULTAR ↗</a></div><div class="setting"><div><h3>CONTA STACKUP ID</h3><p>E-MAIL, ACESSO E SINCRONIZAÇÃO.</p></div><button class="quiet" data-login>ACESSAR ↗</button></div>`;
app.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>img.style.display='none'));
}
document.addEventListener('click',async e=>{const format=e.target.closest('[data-format]'),filter=e.target.closest('[data-filter]'),series=e.target.closest('[data-series]'),integration=e.target.closest('[data-integration]');if(format){prefs.format=format.dataset.format;savePreferences(storage,prefs);render()}if(filter){activeFilter=filter.dataset.filter;render()}if(series){if(series.dataset.series==='HEROES')location.hash='mission';else openDialog(series.dataset.series,'ESTE APP TEM SUA PRÓPRIA MISSÃO NO UNIVERSO STACKUP HOLD’EM. O ACESSO SERÁ CONECTADO QUANDO SUA INTEGRAÇÃO ESTIVER DISPONÍVEL.')}if(integration)openDialog(integration.dataset.integration,'ESTA FUNÇÃO SERÁ HABILITADA QUANDO O SERVIÇO COMPATÍVEL ESTIVER DISPONÍVEL.');if(e.target.closest('[data-help]'))openDialog('EU SOU O POKERINNO.','VOU ACOMPANHAR SUA DESCOBERTA DO POKER DNA. NO HEROES, SUAS DECISÕES REAIS AJUDAM A REVELAR PADRÕES E A IDENTIDADE DO SEU JOGO. COMECE PELA PRIMEIRA MISSÃO.');if(e.target.closest('[data-login]'))location.hash='login';if(e.target.closest('[data-retry]')){state=await loadHeroes(window.StackUpHeroesAdapter);render()}});
document.addEventListener('change',e=>{if(e.target.id==='motion'){prefs.reducedMotion=e.target.checked;const saved=savePreferences(storage,prefs);document.documentElement.classList.toggle('reduced-motion',prefs.reducedMotion);if(!saved)openDialog('AJUSTE APLICADO','SEU NAVEGADOR NÃO PERMITIU SALVAR. A PREFERÊNCIA VALE DURANTE ESTA VISITA.')}});window.addEventListener('stackup:auth',()=>{authenticated=true;render()});window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});render();state=await loadHeroes(window.StackUpHeroesAdapter);render();

enablePageSwipe(nav.map(item=>item[0]));
